// Inlines Leaflet into a TS module so the in-app map works without a CDN.
import { readFileSync, writeFileSync } from 'node:fs';
const js = readFileSync('node_modules/leaflet/dist/leaflet.js', 'utf8');
const css = readFileSync('node_modules/leaflet/dist/leaflet.css', 'utf8');
writeFileSync('src/map/leafletAssets.ts',
  '// Generated by scripts/gen-leaflet.mjs — do not edit.\n' +
  `export const LEAFLET_JS = ${JSON.stringify(js)};\n` +
  `export const LEAFLET_CSS = ${JSON.stringify(css)};\n`);
console.log('leaflet', (js.length / 1024).toFixed(0) + 'KB js', (css.length / 1024).toFixed(0) + 'KB css');
